func TestDuplicatePropertyFails(t *testing.T) {
	pth := filepath.Join(
		ourtesting.TestDataDir,
		"Xml",
		"Expected",
		"something",
		"minimal.xml",
	)

	bb, err := os.ReadFile(pth)
	if err != nil {
		t.Fatalf("Failed to read the file %s: %s", pth, err.Error())
	}

	text := string(bb)

	// We cut the element of the property out of the recorded example and put it in
	// a second time, just before the closing tag of the instance.
	start := strings.Index(text, "<text>")

	var property string
	if start >= 0 {
		end := strings.Index(
			text[start:], "</text>",
		) + start
		property = text[start : end+7]
	} else {
		// The element is written self-closing in the example, an empty list being
		// the usual reason. We write that very element out ourselves.
		property = "<text/>"
	}

	insertionIndex := strings.LastIndex(
		text, "</something>",
	)
	if insertionIndex < 0 {
		t.Fatalf(
			"We expect the recorded example to contain the closing tag %s, "+
				"but it does not: %s",
			"</something>", pth,
		)
	}

	brokenText := text[:insertionIndex] + property + text[insertionIndex:]

	decoder := xml.NewDecoder(strings.NewReader(brokenText))

	_, deseriaErr := ourxmlization.Unmarshal(decoder)
	if deseriaErr == nil {
		t.Fatalf(
			"Expected a de-serialization error when the property %s is given twice, "+
				"but got none",
			"text",
		)
	}
}

// Give the text of the first recorded example of ISomething with
// the content of the element `xmlName` replaced by `text`.
func patchSomethingWith(
	t *testing.T,
	xmlName string,
	text string,
) string {
	pths := ourtesting.FindFilesBySuffixRecursively(
		filepath.Join(
			ourtesting.TestDataDir,
			"Xml",
			"Expected",
			"something",
		),
		".xml",
	)
	sort.Strings(pths)

	if len(pths) == 0 {
		t.Fatalf(
			"Expected at least one recorded example of %s, but got none",
			"something",
		)
	}

	bb, err := os.ReadFile(pths[0])
	if err != nil {
		t.Fatalf("Failed to read the file %s: %s", pths[0], err.Error())
	}

	original := string(bb)

	start := strings.Index(original, "<"+xmlName+">") + len(xmlName) + 2
	end := strings.Index(original, "</"+xmlName+">")

	return original[:start] + text + original[end:]
}

// Read the first recorded example of ISomething with the content of
// the element `xmlName` replaced by `text`.
func readSomethingWith(
	t *testing.T,
	xmlName string,
	text string,
) ourtypes.ISomething {
	patched := patchSomethingWith(t, xmlName, text)

	decoder := xml.NewDecoder(strings.NewReader(patched))
	deserialized, deseriaErr := ourxmlization.Unmarshal(decoder)
	if deseriaErr != nil {
		t.Fatalf(
			"Expected no de-serialization error on %v, but got: %s",
			patched, deseriaErr.Error(),
		)
	}

	instance, ok := deserialized.(ourtypes.ISomething)
	if !ok {
		t.Fatalf("Expected an instance of ISomething, but got %T", deserialized)
	}

	return instance
}

